from pathlib import Path

# Make creative rendering use canonical timeline time and honor simplified quality.
p=Path('lib/lyricforge/render-effects.ts')
s=p.read_text()
s=s.replace("  frameIndex:number;\n  pool?:RenderSurfacePool;", "  frameIndex:number;\n  timeMs:number;\n  pool?:RenderSurfacePool;")
