s=s.replace("  const radius=numberParam(effect,'radius',22),intensity=clamp01(numberParam(effect,'intensity',.45));", "  const radius=numberParam(effect,'radius',22)*(effect.quality==='simplified'?.5:1),intensity=clamp01(numberParam(effect,'intensity',.45));")
s=s.replace("const renderSharpen:EffectRenderHandler=(ctx,source,effect,env)=>withFilter(ctx,source,env,`contrast(${1+numberParam(effect,'amount',.4)*.3}) saturate(${1+numberParam(effect,'amount',.4)*.08})`);", "const renderSharpen:EffectRenderHandler=(ctx,source,effect,env)=>{const amount=numberParam(effect,'amount',.4)*(effect.quality==='simplified'?.5:1);withFilter(ctx,source,env,`contrast(${1+amount*.3}) saturate(${1+amount*.08})`);};")
s=s.replace("  const size=Math.max(1,numberParam(effect,'size',1));const cells=Math.min(900,Math.ceil(env.width*env.height/Math.max(1,size*size*250)));", "  const size=Math.max(1,numberParam(effect,'size',1));const baseCells=Math.min(900,Math.ceil(env.width*env.height/Math.max(1,size*size*250))),cells=Math.max(1,Math.floor(baseCells*(effect.quality==='simplified'?.25:1)));")
s=s.replace("  const size=Math.max(1,Math.round(numberParam(effect,'size',8)));", "  const size=Math.max(1,Math.round(numberParam(effect,'size',8)*(effect.quality==='simplified'?2:1)));")
s=s.replace("  ctx.save();ctx.globalAlpha=scanlines*.25;ctx.fillStyle='#000000';for(let y=0;y<env.height;y+=4)ctx.fillRect(0,y,env.width,1);ctx.globalAlpha=noise*.2;ctx.fillStyle=seeded(effect,env,99)>.5?'#ffffff':'#000000';for(let i=0;i<60;i++){ctx.fillRect(seeded(effect,env,i*31)*env.width,seeded(effect,env,i*47+7)*env.height,1,1);}ctx.restore();", "  const scanStep=effect.quality==='simplified'?8:4,noiseDots=effect.quality==='simplified'?20:60;ctx.save();ctx.globalAlpha=scanlines*.25;ctx.fillStyle='#000000';for(let y=0;y<env.height;y+=scanStep)ctx.fillRect(0,y,env.width,1);ctx.globalAlpha=noise*.2;ctx.fillStyle=seeded(effect,env,99)>.5?'#ffffff':'#000000';for(let i=0;i<noiseDots;i++){ctx.fillRect(seeded(effect,env,i*31)*env.width,seeded(effect,env,i*47+7)*env.height,1,1);}ctx.restore();")
s=s.replace("  const amount=numberParam(effect,'amount',8),band=Math.max(2,Math.round(numberParam(effect,'scale',24)));", "  const amount=numberParam(effect,'amount',8),band=Math.max(2,Math.round(numberParam(effect,'scale',24)*(effect.quality==='simplified'?2:1)));")
s=s.replace("  const amount=numberParam(effect,'amount',8),speed=numberParam(effect,'speed',8),phase=env.frameIndex*Math.max(.01,speed)*.13;", "  const amount=numberParam(effect,'amount',8),speed=numberParam(effect,'speed',8),phase=env.timeMs/1000*Math.max(.01,speed)*7.8;")
s=s.replace("  const amount=numberParam(effect,'amount',.08),period=Math.max(100,numberParam(effect,'periodMs',800)),t=env.frameIndex*1000/60,scale=1+Math.sin(t/period*Math.PI*2)*amount;", "  const amount=numberParam(effect,'amount',.08),period=Math.max(100,numberParam(effect,'periodMs',800)),t=env.timeMs,scale=1+Math.sin(t/period*Math.PI*2)*amount;")
s=s.replace("  const intensity=clamp01(numberParam(effect,'intensity',.35)),rate=clamp01(numberParam(effect,'rate',.25));if(seeded(effect,env,5)>rate){draw(ctx,source,env);return;}draw(ctx,source,env);const slices=Math.max(2,Math.round(3+intensity*10));", "  const intensity=clamp01(numberParam(effect,'intensity',.35)),rate=clamp01(numberParam(effect,'rate',.25));if(seeded(effect,env,5)>rate){draw(ctx,source,env);return;}draw(ctx,source,env);const slices=Math.max(2,Math.round((3+intensity*10)*(effect.quality==='simplified'?.5:1)));")
p.write_text(s)

