p=Path('lib/lyricforge/renderer.ts')
s=p.read_text()
s=s.replace("renderEffect(target.ctx,current,effect,{width:p.width,height:p.height,frameIndex,pool:this.surfaces})", "renderEffect(target.ctx,current,effect,{width:p.width,height:p.height,frameIndex,timeMs:time,pool:this.surfaces})")
